// Ask the Mac which feeds to read, then hand it each feed URL: the Mac fetches and parses it (Reddit refuses requests from
// this container), checks every idea and writes them. n8n only triggers. One failing feed never stops the others.
const mac = 'http://host.docker.internal:5680';
const list = await this.helpers.httpRequest({ url: `${mac}/feeds`, json: true });
const out = [];
for (const f of list) {
  await new Promise((r) => setTimeout(r, 8000)); // Reddit rate-limits quick repeats (429)
  try {
    const r = await this.helpers.httpRequest({ method: 'POST', url: `${mac}/feed`, body: { url: f.url }, json: true, timeout: 60000 });
    out.push({ json: { url: f.url, added: r.added.length, skipped: r.skipped.length } });
  } catch (e) {
    out.push({ json: { url: f.url, error: e.message } });
  }
}
return out;
